var (
	VMInterfaceRegexp = regexp.MustCompile(`eth[1-9]\d*$`) // skipcq: GO-C4007
	imageTagRE        = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]*$`)
